CONVERSATION_PANEL_CLASS = {
  /** The new-chat button. */
  newChatButton: 'dial-cp-new-chat-button',
  /** The `role="search"` wrapper around the conversation search field. */
  search: 'dial-cp-search',
} as const

ConversationPanel: FC<ConversationPanelProps> = memo(
  ({
    conversations,
    isLoading,
    isOpen,
    onSelectConversation,
    activeConversationId,
    labels,
    onNewChat,
    styles: panelStyles,
    className,
    isOverlay = false,
    getActions,
    onActionMenuOpen,
    onToggle,
    headerActions,
    onMoveConversation,
    activeFilter,
    onActiveFilterChange,
    isFilterTabsHidden = false,
    hiddenSources,
  }) => {
    const {
      colors,
      typography,
      newChatButton: newChatButtonColors,
      searchWrapperClassName,
    } = panelStyles ?? {};

    const {
      title,
      emptyLabel,
      noResultsLabel,
      loadingLabel = 'Loading conversations',
      newChatLabel,
      searchPlaceholder,
      searchClearLabel,
      filterLabels,
      groupLabels,
      actionsLabel,
      unreadIndicatorLabel,
      closeAriaLabel,
    } = labels;
    const [searchQuery, setSearchQuery] = useState('');
    const [activeTab, setActiveTab] = useState(FilterTab.All);

    useEffect(() => {
      if (activeFilter == null) return;
      setActiveTab(activeFilter);
    }, [activeFilter]);

    /*
     * Dropped before any tab/search filtering so a hidden source never
     * surfaces under `All` or as a group heading, not just off its own tab.
     */
    const visibleConversations = useMemo(
      () =>
        hiddenSources?.length
          ? conversations.filter(
              (item) =>
                item.source == null || !hiddenSources.includes(item.source),
            )
          : conversations,
      [conversations, hiddenSources],
    );

    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(
      () => ALL_GROUP_KEYS,
    );
    const [overscanCount, setOverscanCount] = useState(5);
    const listId = useId();
    const listRef = useRef<ListImperativeAPI>(null);
    const lastScrolledIdRef = useRef<string | null>(null);

    const [draggingId, setDraggingId] = useState<string | null>(null);
    const [dragOverId, setDragOverId] = useState<string | null>(null);
    const [allowedDropGroups, setAllowedDropGroups] =
      useState<Set<FilterTab> | null>(null);

    /*
     * Refs let the drop handler read current values without being in the useCallback dep array,
     * avoiding recreating the handler (and remounting rows) on every drag-state change.
     */
    const draggingIdRef = useRef<string | null>(null);
    const allowedDropGroupsRef = useRef<Set<FilterTab> | null>(null);

    const handleListResize = useCallback(({ height }: { height: number }) => {
      setOverscanCount(Math.ceil((height / ITEM_ROW_HEIGHT) * 2));
    }, []);

    const handleSearchChange = useCallback((value?: string) => {
      setSearchQuery(value ?? '');
    }, []);

    const handleToggleGroup = useCallback((key: string) => {
      setExpandedGroups((prev) => {
        const next = new Set(prev);
        if (next.has(key)) {
          next.delete(key);
        } else {
          next.add(key);
        }
        return next;
      });
    }, []);

    const clearDragState = useCallback(() => {
      draggingIdRef.current = null;
      allowedDropGroupsRef.current = null;
      setDraggingId(null);
      setDragOverId(null);
      setAllowedDropGroups(null);
    }, []);

    const handleDragStart = useCallback(
      (id: string, rows: VirtualRow[]) => {
        const groupKey = findGroupKeyForItem(rows, id);
        const allowed = computeAllowedDropGroups(
          id,
          groupKey,
          visibleConversations,
        );
        draggingIdRef.current = id;
        allowedDropGroupsRef.current = allowed;
        setDraggingId(id);
        setAllowedDropGroups(allowed);
      },
      [visibleConversations],
    );

    const handleDragEnd = useCallback(() => {
      clearDragState();
    }, [clearDragState]);

    const handleDragOver = useCallback((id: string) => {
      setDragOverId(id);
    }, []);

    const handleDragLeave = useCallback(() => {
      setDragOverId(null);
    }, []);

    const handleDrop = useCallback(
      (targetId: string, targetGroupKey: FilterTab, afterId: string | null) => {
        const currentDraggingId = draggingIdRef.current;
        const currentAllowed = allowedDropGroupsRef.current;
        clearDragState();
        if (
          currentDraggingId != null &&
          currentDraggingId !== targetId &&
          currentAllowed?.has(targetGroupKey)
        ) {
          onMoveConversation?.({
            draggedId: currentDraggingId,
            targetGroupKey,
            afterId,
          });
        }
      },
      [clearDragState, onMoveConversation],
    );

    const cssVars = buildCssVars({
      '--cp-item-hover': colors?.itemHover,
      '--cp-item-active': colors?.itemActive,
      '--cp-text': colors?.text,
      '--cp-text-secondary': colors?.textSecondary,
      '--cp-new-chat-bg': newChatButtonColors?.background,
      '--cp-new-chat-text': newChatButtonColors?.text,
      '--cp-new-chat-focus-outline': newChatButtonColors?.focusOutline,
      '--cp-drop-zone-ring': colors?.dropZoneRing,
      '--cp-trigger-bg': colors?.triggerBackground,
      '--cp-trigger-icon': colors?.triggerIcon,
      '--cp-trigger-icon-idle': colors?.triggerIconIdle,
      '--cp-skeleton-color': colors?.skeletonColor,
      '--cp-task-badge-border': colors?.taskBadgeBorder,
      '--cp-task-badge-bg': colors?.taskBadgeBackground,
      '--cp-task-badge-text': colors?.taskBadgeText,
      '--cp-unread-dot': colors?.unreadDot,
    });

    const filteredItems = useMemo(
      () =>
        visibleConversations.filter(
          (item) =>
            matchesTab(item, activeTab) && matchesSearch(item, searchQuery),
        ),
      [visibleConversations, activeTab, searchQuery],
    );

    const pinnedItems = useMemo(
      () => filteredItems.filter((item) => item.isPinned),
      [filteredItems],
    );

    const myChatsItems = useMemo(
      () =>
        filteredItems.filter(
          (item) =>
            !item.isPinned &&
            item.source !== FilterTab.Shared &&
            item.source !== FilterTab.Organization,
        ),
      [filteredItems],
    );

    const sharedItems = useMemo(
      () =>
        filteredItems.filter(
          (item) => !item.isPinned && item.source === FilterTab.Shared,
        ),
      [filteredItems],
    );

    const organizationItems = useMemo(
      () =>
        filteredItems.filter(
          (item) => !item.isPinned && item.source === FilterTab.Organization,
        ),
      [filteredItems],
    );

    const groups = useMemo(
      () => [
        {
          key: FilterTab.Pinned,
          label: groupLabels?.pinned ?? 'Pinned',
          items: pinnedItems,
        },
        {
          key: FilterTab.MyChats,
          label: groupLabels?.myChats ?? 'My chats',
          items: myChatsItems,
        },
        {
          key: FilterTab.Shared,
          label: groupLabels?.shared ?? 'Shared',
          items: sharedItems,
        },
        {
          key: FilterTab.Organization,
          label: groupLabels?.organization ?? 'Organization',
          items: organizationItems,
        },
      ],
      [groupLabels, pinnedItems, myChatsItems, sharedItems, organizationItems],
    );

    const virtualRows = useMemo(() => {
      const rows: VirtualRow[] = [];
      for (const group of groups) {
        if (group.items.length === 0) continue;
        rows.push({
          kind: VirtualRowKind.Header,
          groupKey: group.key,
          label: group.label,
        });
        if (expandedGroups.has(group.key)) {
          for (const item of group.items) {
            rows.push({ kind: VirtualRowKind.Item, item, groupKey: group.key });
          }
        }
      }
      return rows;
    }, [groups, expandedGroups]);

    useEffect(() => {
      if (!activeConversationId) return;

      if (lastScrolledIdRef.current === activeConversationId) return;

      const index = virtualRows.findIndex(
        (row) =>
          row.kind === VirtualRowKind.Item &&
          row.item.id === activeConversationId,
      );
      if (index >= 0) {
        listRef.current?.scrollToRow({
          index,
          align: 'smart',
          behavior: 'smooth',
        });
        lastScrolledIdRef.current = activeConversationId;
      }
    }, [activeConversationId, groups, expandedGroups, virtualRows]);

    const rowProps = useMemo<RowRendererData>(
      () => ({
        rows: virtualRows,
        expandedGroups,
        onToggleGroup: handleToggleGroup,
        listId,
        activeConversationId,
        searchQuery,
        onSelectConversation,
        getActions,
        onActionMenuOpen,
        actionsLabel,
        unreadIndicatorLabel,
        styles: {
          groupHeaderClassName: typography?.groupHeaderClassName,
          itemTitleClassName: typography?.itemTitleClassName,
          itemIconBadgeClassName: panelStyles?.itemIconBadgeClassName,
          taskBadgeClassName: panelStyles?.taskBadgeClassName,
        },
        draggingId,
        dragOverId,
        allowedDropGroups,
        onDragStart: (id: string) => handleDragStart(id, virtualRows),
        onDragEnd: handleDragEnd,
        onDragOver: handleDragOver,
        onDragLeave: handleDragLeave,
        onDrop: handleDrop,
      }),
      [
        virtualRows,
        expandedGroups,
        handleToggleGroup,
        listId,
        activeConversationId,
        searchQuery,
        onSelectConversation,
        getActions,
        onActionMenuOpen,
        actionsLabel,
        unreadIndicatorLabel,
        typography?.groupHeaderClassName,
        typography?.itemTitleClassName,
        panelStyles?.itemIconBadgeClassName,
        panelStyles?.taskBadgeClassName,
        draggingId,
        dragOverId,
        allowedDropGroups,
        handleDragStart,
        handleDragEnd,
        handleDragOver,
        handleDragLeave,
        handleDrop,
      ],
    );

    const isNoConversations = visibleConversations.length === 0;
    const isNoResults =
      visibleConversations.length > 0 && filteredItems.length === 0;

    return (
      <SidebarPanel
        isOpen={isOpen}
        isOverlay={isOverlay}
        orientation={SidebarOrientation.Left}
        title={title}
        labels={{ ariaLabel: title, closeLabel: closeAriaLabel }}
        onClose={onToggle}
        styles={{
          colors: {
            background: colors?.background,
            border: colors?.border,
          },
          typography: {
            fontClassName: typography?.fontClassName,
          },
          bodyClassName: 'flex flex-col overflow-hidden p-0 gap-3',
          cssVars,
          titleClassName: typography?.fontClassName,
          headerClassName: 'h-[64px]',
          className: mergeClasses(
            isOpen ? 'w-[324px] mobile:w-full' : 'w-0',
            className,
          ),
        }}
        rightActions={headerActions}
      >
        <NewChatButton
          label={newChatLabel}
          onClick={onNewChat}
          labelClassName={typography?.newChatLabelClassName}
          colors={newChatButtonColors}
        />

        <div
          role="search"
          className={mergeClasses('px-3 py-2', CONVERSATION_PANEL_CLASS.search)}
        >
          <Search
            wrapperClassName={mergeClasses(
              styles.search,
              searchWrapperClassName,
            )}
            value={searchQuery}
            onChange={handleSearchChange}
            placeholder={searchPlaceholder}
            clearLabel={searchClearLabel}
            aria-label={searchPlaceholder}
          />
        </div>

        {!isFilterTabsHidden && (
          <FilterTabs
            activeTab={activeTab}
            labels={filterLabels}
            onChange={(tab) => {
              setActiveTab(tab);
              onActiveFilterChange?.(tab);
            }}
            tabClassName={typography?.tabClassName}
            hiddenSources={hiddenSources}
          />
        )}

        <span role="status" aria-live="polite" className="sr-only">
          {isLoading
            ? loadingLabel
            : isNoConversations
              ? emptyLabel
              : isNoResults
                ? noResultsLabel
                : ''}
        </span>

        <div className="flex-1 overflow-hidden py-1 pe-3 ps-2">
          {isLoading ? (
            <div className="flex flex-col gap-3 px-2 py-3">
              {Array.from({ length: SKELETON_ROW_COUNT }, (_, i) => (
                <Skeleton
                  key={i}
                  avatar={{ size: 24 }}
                  showTitle={{ width: getSkeletonWidth(i) }}
                  paragraph={false}
                  active
                  color={styles.skeletonColor}
                />
              ))}
            </div>
          ) : isNoConversations ? (
            <PanelEmpty label={emptyLabel} />
          ) : isNoResults ? (
            <PanelNoResults label={noResultsLabel} />
          ) : (
            <List<RowRendererData>
              listRef={listRef}
              id={listId}
              role="list"
              style={{ height: '100%' }}
              rowComponent={RowRenderer}
              rowCount={virtualRows.length}
              rowHeight={getRowHeight}
              overscanCount={overscanCount}
              onResize={handleListResize}
              rowProps={rowProps}
            />
          )}
        </div>
      </SidebarPanel>
    );
  },
)

ImportExportQueue: FC<ImportExportQueueProps> = memo(
  ({ title, jobs, onClose, onCancel, labels, styles }) => {
    const [isCollapsed, setIsCollapsed] = useState(false);
    const jobsId = useId();
    const [isConfirmOpen, setIsConfirmOpen] = useState(false);
    const colors = styles?.colors;
    const cssVars = {
      ...buildCssVars({
        '--cp-transfer-queue-bg': colors?.background,
        '--cp-transfer-queue-text': colors?.text,
        '--cp-transfer-queue-text-secondary': colors?.textSecondary,
        '--cp-transfer-queue-success-icon': colors?.successIcon,
        '--cp-transfer-queue-error-icon': colors?.errorIcon,
        '--cp-transfer-queue-warning-icon': colors?.warningIcon,
        '--cp-transfer-queue-divider': colors?.divider,
        '--cp-transfer-queue-failure-count-bg': colors?.failureCountBackground,
        '--cp-transfer-queue-failure-count-text': colors?.failureCountText,
      }),
      ...styles?.cssVars,
    };

    const hasInProgress = jobs.some(
      (job) => job.status === ConversationTransferJobStatus.InProgress,
    );
    const hasFailed = jobs.some(
      (job) => job.status === ConversationTransferJobStatus.Failed,
    );
    const isEverySucceeded =
      jobs.length > 0 &&
      jobs.every((job) => job.status === ConversationTransferJobStatus.Success);

    const handleClose = useCallback(() => {
      if (hasInProgress || hasFailed) {
        setIsConfirmOpen(true);
      } else {
        onClose();
      }
    }, [hasInProgress, hasFailed, onClose]);

    const handleConfirmClose = useCallback(() => {
      setIsConfirmOpen(false);
      onClose();
    }, [onClose]);

    const handleToggleCollapse = useCallback(() => {
      setIsCollapsed((value) => !value);
    }, []);

    useEffect(() => {
      if (!isEverySucceeded) return undefined;

      const timeoutId = setTimeout(onClose, AUTO_CLOSE_DELAY_MS);
      return () => clearTimeout(timeoutId);
    }, [isEverySucceeded, onClose]);

    if (jobs.length === 0) return null;

    const failedCount = jobs.filter(
      (job) => job.status === ConversationTransferJobStatus.Failed,
    ).length;

    return (
      <div
        role="status"
        aria-live="polite"
        style={cssVars}
        className={mergeClasses(
          classes.root,
          'w-[370px] max-w-[calc(100vw-2rem)] rounded-xl shadow-md',
          styles?.rootClassName,
        )}
      >
        <ImportExportQueueHeader
          title={title}
          failedCount={failedCount}
          isCollapsed={isCollapsed}
          jobsId={jobsId}
          labels={labels}
          styles={styles}
          onToggleCollapse={handleToggleCollapse}
          onClose={handleClose}
        />
        {isCollapsed && hasInProgress && (
          /*
           * Only while collapsed: expanded, every row already carries its own
           * spinner, so an aggregate bar would restate what is on screen.
           * Collapsed, the rows are unmounted and nothing else says work
           * continues.
           */
          <ProgressBar
            value={getAggregatePercent(jobs)}
            size={ElementSize.Small}
            aria-label={labels.queueProgressAriaLabel}
            aria-valuetext={labels.queueProgressValueText(
              getSettledCount(jobs),
              jobs.length,
            )}
          />
        )}
        {!isCollapsed && (
          <div
            id={jobsId}
            className={mergeClasses(
              'flex max-h-[40vh] flex-col overflow-y-auto py-1',
              styles?.bodyClassName,
            )}
          >
            {jobs.map((job) => (
              <ImportExportQueueRow
                key={job.id}
                job={job}
                labels={labels}
                onCancel={onCancel}
                styles={styles}
              />
            ))}
          </div>
        )}
        <ConfirmationPopup
          open={isConfirmOpen}
          header={labels.closeQueueConfirmHeader}
          description={getCloseConfirmDescription(
            hasInProgress,
            hasFailed,
            labels,
          )}
          confirmLabel={labels.closeLabel}
          cancelLabel={labels.cancelLabel}
          variant={ConfirmationPopupVariant.Danger}
          onConfirm={handleConfirmClose}
          onClose={() => setIsConfirmOpen(false)}
        />
      </div>
    );
  },
)

RenameConversationPopup: FC<RenameConversationPopupProps> = memo(
  ({
    isOpen,
    currentTitle,
    isSaving,
    error,
    onSave,
    onCancel,
    onGenerateWithAi,
    labels,
    styles,
  }) => {
    const [value, setValue] = useState(currentTitle);
    const [isGenerating, setIsGenerating] = useState(false);
    const [generateError, setGenerateError] = useState<string | null>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const wasOpenRef = useRef(false);
    const generationIdRef = useRef(0);

    useEffect(() => {
      const hasJustOpened = isOpen && !wasOpenRef.current;
      wasOpenRef.current = isOpen;
      if (!isOpen) {
        generationIdRef.current += 1;
        setIsGenerating(false);
        return undefined;
      }
      if (!hasJustOpened) return undefined;

      generationIdRef.current += 1;
      setValue(currentTitle);
      setGenerateError(null);
      setIsGenerating(false);
      /* Defer focus so the popup has time to mount and become visible. */
      const timeoutId = setTimeout(() => inputRef.current?.focus(), 0);
      return () => clearTimeout(timeoutId);
    }, [isOpen, currentTitle]);

    useEffect(
      () => () => {
        generationIdRef.current += 1;
      },
      [],
    );

    const trimmed = stripTrailingDots(value.trim());
    const isTooLong = getUtf8ByteLength(trimmed) > 255;
    const isSaveDisabled =
      isSaving ||
      trimmed === '' ||
      trimmed === currentTitle.trim() ||
      isTooLong;

    const handleSave = useCallback(() => {
      if (!isSaveDisabled) onSave(trimmed);
    }, [isSaveDisabled, onSave, trimmed]);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') handleSave();
      },
      [handleSave],
    );

    const handleGenerateWithAi = useCallback(async () => {
      if (isGenerating) return;
      const generationId = ++generationIdRef.current;
      setIsGenerating(true);
      setGenerateError(null);
      try {
        const generatedName = await onGenerateWithAi();
        if (generationId !== generationIdRef.current) return;
        setValue(sanitizeConversationName(generatedName));
      } catch {
        if (generationId !== generationIdRef.current) return;
        setGenerateError(labels.renameWithAiError);
      } finally {
        if (generationId === generationIdRef.current) {
          setIsGenerating(false);
        }
      }
    }, [isGenerating, onGenerateWithAi, labels.renameWithAiError]);

    let inputError: string | undefined;
    if (isTooLong) {
      inputError = labels.nameTooLongError;
    } else {
      inputError = generateError ?? error ?? undefined;
    }

    return (
      <Popup
        open={isOpen}
        header={labels.popupTitle}
        size={PopupSize.Sm}
        onClose={onCancel}
        mainButtons={
          isSaving
            ? undefined
            : [
                { label: labels.cancelLabel, onClick: onCancel },
                {
                  label: labels.saveLabel,
                  variant: ButtonVariant.Primary,
                  disabled: isSaveDisabled,
                  onClick: handleSave,
                },
              ]
        }
      >
        <div className={styles?.bodyClassName} style={styles?.cssVars}>
          {isSaving ? (
            <div className="h-[120px] px-6 py-4">
              <Spinner size={50} />
            </div>
          ) : (
            <div className="flex items-start gap-2 px-6 py-3">
              <div className="min-w-0 flex-1">
                <Input
                  inputRef={inputRef}
                  value={value}
                  placeholder={labels.inputPlaceholder}
                  error={inputError}
                  onChange={(v) => setValue(sanitizeConversationName(v ?? ''))}
                  onKeyDown={handleKeyDown}
                />
              </div>
              <GhostIconButton
                aria-label={labels.renameWithAiLabel}
                tooltipProps={{ tooltip: labels.renameWithAiLabel }}
                disabled={isGenerating || isSaving}
                onClick={handleGenerateWithAi}
                icon={
                  isGenerating ? (
                    <Spinner size={DIAL_ICON_SIZE.MD} />
                  ) : (
                    <IconSparkles
                      size={DIAL_ICON_SIZE.MD}
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  )
                }
              />
            </div>
          )}
        </div>
      </Popup>
    );
  },
)

export interface RenameConversationPopupProps {
  /** Whether the popup is visible. */
  isOpen: boolean;
  /** The conversation's current name, pre-filled into the input on open. */
  currentTitle: string;
  /** While `true`, the input/buttons are replaced by a loading indicator. */
  isSaving: boolean;
  /** API-level error message, or `null` when none. */
  error: string | null;
  /** Called with the trimmed, sanitized new name when the user confirms. */
  onSave: (newTitle: string) => void;
  /** Called when the user cancels or closes the popup. */
  onCancel: () => void;
  /** Called to request an AI-generated name; must resolve with the generated string. */
  onGenerateWithAi: () => Promise<string>;
  /** User-visible string labels. */
  labels: RenameConversationPopupLabels;
  /** Class and CSS-variable overrides for the popup content. */
  styles?: RenameConversationPopupStyles;
}

export interface RenameConversationPopupLabels {
  /** Popup dialog heading. */
  popupTitle: string;
  /** Placeholder text for the name input. */
  inputPlaceholder: string;
  /** Accessible name and tooltip for the AI-generation trigger button. */
  renameWithAiLabel: string;
  /** Error shown when the AI name generation request fails. */
  renameWithAiError: string;
  /** Error shown when the trimmed name's UTF-8 byte length exceeds 255. */
  nameTooLongError: string;
  /** Label for the save/confirm button. */
  saveLabel: string;
  /** Label for the cancel button. */
  cancelLabel: string;
}

export interface RenameConversationPopupStyles {
  /** Extra class name(s) merged onto the popup body wrapper. */
  bodyClassName?: string;
  /** Arbitrary CSS custom properties inherited by the popup content. */
  cssVars?: CSSProperties;
}

export interface ImportExportQueueProps {
  /**
   * Queue panel heading, rendered verbatim. The host composes any count into
   * it (e.g. `t(key, { count: jobs.length })`); the component never pluralizes.
   */
  title: string;
  /** Current list of transfer jobs. */
  jobs: ConversationTransferJob[];
  /** Called when the queue should close (after confirmation if needed). */
  onClose: () => void;
  /**
   * Called with the job id when the user cancels an in-progress job. The host
   * is expected to abort the work and leave the job in `jobs` with status
   * `Canceled`.
   */
  onCancel: (jobId: string) => void;
  /** User-visible string labels. */
  labels: ImportExportQueueLabels;
  /** Color, typography, class, and CSS-variable overrides. */
  styles?: ImportExportQueueStyles;
}

export interface ImportExportQueueLabels {
  /** Returns the accessible name for the cancel control of an in-progress job. */
  cancelJobAriaLabel: (fileName: string) => string;
  /** Trailing text shown on a canceled row. */
  canceledLabel: string;
  /** Returns the tooltip text explaining why a job failed. */
