    const [isConfirmOpen, setIsConfirmOpen] = useState(false);
    const colors = styles?.colors;
    const cssVars = {
      ...buildCssVars({
        '--cp-transfer-queue-bg': colors?.background,
        '--cp-transfer-queue-text': colors?.text,
        '--cp-transfer-queue-text-secondary': colors?.textSecondary,
        '--cp-transfer-queue-success-icon': colors?.successIcon,
        '--cp-transfer-queue-error-icon': colors?.errorIcon,
        '--cp-transfer-queue-warning-icon': colors?.warningIcon,
        '--cp-transfer-queue-divider': colors?.divider,
        '--cp-transfer-queue-failure-count-bg': colors?.failureCountBackground,
        '--cp-transfer-queue-failure-count-text': colors?.failureCountText,
      }),
      ...styles?.cssVars,
    };

    const hasInProgress = jobs.some(
      (job) => job.status === ConversationTransferJobStatus.InProgress,
    );
    const hasFailed = jobs.some(
      (job) => job.status === ConversationTransferJobStatus.Failed,
    );
    const isEverySucceeded =
      jobs.length > 0 &&
      jobs.every((job) => job.status === ConversationTransferJobStatus.Success);

    const handleClose = useCallback(() => {
      if (hasInProgress || hasFailed) {
        setIsConfirmOpen(true);
      } else {
        onClose();
      }
    }, [hasInProgress, hasFailed, onClose]);

    const handleConfirmClose = useCallback(() => {
      setIsConfirmOpen(false);
      onClose();
    }, [onClose]);

    const handleToggleCollapse = useCallback(() => {
      setIsCollapsed((value) => !value);
    }, []);

    useEffect(() => {
      if (!isEverySucceeded) return undefined;

      const timeoutId = setTimeout(onClose, AUTO_CLOSE_DELAY_MS);
      return () => clearTimeout(timeoutId);
    }, [isEverySucceeded, onClose]);

    if (jobs.length === 0) return null;

    const failedCount = jobs.filter(
      (job) => job.status === ConversationTransferJobStatus.Failed,
    ).length;

    return (
      <div
        role="status"
        aria-live="polite"
        style={cssVars}
        className={mergeClasses(
          classes.root,
          'w-[370px] max-w-[calc(100vw-2rem)] rounded-xl shadow-md',
          styles?.rootClassName,
        )}
      >
        <ImportExportQueueHeader
          title={title}
          failedCount={failedCount}
          isCollapsed={isCollapsed}
          jobsId={jobsId}
          labels={labels}
          styles={styles}
          onToggleCollapse={handleToggleCollapse}
          onClose={handleClose}
        />
        {isCollapsed && hasInProgress && (
          /*
           * Only while collapsed: expanded, every row already carries its own
           * spinner, so an aggregate bar would restate what is on screen.
           * Collapsed, the rows are unmounted and nothing else says work
           * continues.
           */
          <ProgressBar
            value={getAggregatePercent(jobs)}
            size={ElementSize.Small}
            aria-label={labels.queueProgressAriaLabel}
            aria-valuetext={labels.queueProgressValueText(
              getSettledCount(jobs),
              jobs.length,
            )}
          />
        )}
        {!isCollapsed && (
          <div
            id={jobsId}
            className={mergeClasses(
              'flex max-h-[40vh] flex-col overflow-y-auto py-1',
              styles?.bodyClassName,
            )}
          >
            {jobs.map((job) => (
              <ImportExportQueueRow
                key={job.id}
                job={job}
                labels={labels}
                onCancel={onCancel}
                styles={styles}
              />
            ))}
          </div>
        )}
        <ConfirmationPopup
          open={isConfirmOpen}
          header={labels.closeQueueConfirmHeader}
          description={getCloseConfirmDescription(
            hasInProgress,
            hasFailed,
            labels,
          )}
          confirmLabel={labels.closeLabel}
          cancelLabel={labels.cancelLabel}
          variant={ConfirmationPopupVariant.Danger}
          onConfirm={handleConfirmClose}
          onClose={() => setIsConfirmOpen(false)}
        />
      </div>
    );
  },
)

RenameConversationPopup: FC<RenameConversationPopupProps> = memo(
  ({
    isOpen,
    currentTitle,
    isSaving,
    error,
    onSave,
    onCancel,
    onGenerateWithAi,
    labels,
    styles,
  }) => {
    const [value, setValue] = useState(currentTitle);
    const [isGenerating, setIsGenerating] = useState(false);
    const [generateError, setGenerateError] = useState<string | null>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const wasOpenRef = useRef(false);
    const generationIdRef = useRef(0);

    useEffect(() => {
      const hasJustOpened = isOpen && !wasOpenRef.current;
      wasOpenRef.current = isOpen;
      if (!isOpen) {
        generationIdRef.current += 1;
        setIsGenerating(false);
        return undefined;
      }
      if (!hasJustOpened) return undefined;

      generationIdRef.current += 1;
      setValue(currentTitle);
      setGenerateError(null);
      setIsGenerating(false);
      /* Defer focus so the popup has time to mount and become visible. */
      const timeoutId = setTimeout(() => inputRef.current?.focus(), 0);
      return () => clearTimeout(timeoutId);
    }, [isOpen, currentTitle]);

    useEffect(
      () => () => {
        generationIdRef.current += 1;
      },
      [],
    );

    const trimmed = stripTrailingDots(value.trim());
    const isTooLong = getUtf8ByteLength(trimmed) > 255;
    const isSaveDisabled =
      isSaving ||
      trimmed === '' ||
      trimmed === currentTitle.trim() ||
      isTooLong;

    const handleSave = useCallback(() => {
      if (!isSaveDisabled) onSave(trimmed);
    }, [isSaveDisabled, onSave, trimmed]);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') handleSave();
      },
      [handleSave],
    );

    const handleGenerateWithAi = useCallback(async () => {
      if (isGenerating) return;
      const generationId = ++generationIdRef.current;
      setIsGenerating(true);
      setGenerateError(null);
      try {
        const generatedName = await onGenerateWithAi();
        if (generationId !== generationIdRef.current) return;
        setValue(sanitizeConversationName(generatedName));
      } catch {
        if (generationId !== generationIdRef.current) return;
        setGenerateError(labels.renameWithAiError);
      } finally {
        if (generationId === generationIdRef.current) {
          setIsGenerating(false);
        }
      }
    }, [isGenerating, onGenerateWithAi, labels.renameWithAiError]);

    let inputError: string | undefined;
    if (isTooLong) {
      inputError = labels.nameTooLongError;
    } else {
      inputError = generateError ?? error ?? undefined;
    }

    return (
      <Popup
        open={isOpen}
        header={labels.popupTitle}
        size={PopupSize.Sm}
        onClose={onCancel}
        mainButtons={
          isSaving
            ? undefined
            : [
                { label: labels.cancelLabel, onClick: onCancel },
                {
                  label: labels.saveLabel,
                  variant: ButtonVariant.Primary,
                  disabled: isSaveDisabled,
                  onClick: handleSave,
                },
              ]
        }
      >
        <div className={styles?.bodyClassName} style={styles?.cssVars}>
          {isSaving ? (
            <div className="h-[120px] px-6 py-4">
              <Spinner size={50} />
            </div>
          ) : (
            <div className="flex items-start gap-2 px-6 py-3">
              <div className="min-w-0 flex-1">
                <Input
                  inputRef={inputRef}
                  value={value}
                  placeholder={labels.inputPlaceholder}
                  error={inputError}
                  onChange={(v) => setValue(sanitizeConversationName(v ?? ''))}
                  onKeyDown={handleKeyDown}
                />
              </div>
              <GhostIconButton
                aria-label={labels.renameWithAiLabel}
                tooltipProps={{ tooltip: labels.renameWithAiLabel }}
                disabled={isGenerating || isSaving}
                onClick={handleGenerateWithAi}
                icon={
                  isGenerating ? (
                    <Spinner size={DIAL_ICON_SIZE.MD} />
                  ) : (
                    <IconSparkles
                      size={DIAL_ICON_SIZE.MD}
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  )
                }
              />
            </div>
          )}
        </div>
      </Popup>
    );
  },
)

getTransferFileIcon = (fileName: string): TransferFileIcon => {
  const lowerName = fileName.toLowerCase();
  if (ARCHIVE_EXTENSIONS.some((extension) => lowerName.endsWith(extension))) {
    return IconFileZip;
  }
  if (lowerName.endsWith('.json')) {
    return IconJson;
  }
  return IconFile;
}

